const subjects = ["IT", "Quant", "Reasoning", "English", "Finance", "Computer"];
const subject = subjects[Math.floor(Math.random() * subjects.length)];
const date = new Date();
const year = date.getFullYear();
const month = String(date.getMonth() + 1).padStart(2, '0');
const map_sub = { "IT": "Questions", "Quant": "Quant", "Reasoning": "Reasoning", "English": "Eng", "Finance": "Finance", "Computer": "Comp" };
const sheetName = `${map_sub[subject] || 'Questions'}_${year}_${month}`;
return { json: { subject: subject, sheetName: sheetName } };

