let text = items[0].json.candidates[0].content.parts[0].text;
text = text.replace(/```json/g, '').replace(/```/g, '').trim();
const questions = JSON.parse(text);
const subject = $('Pick Subject').item.json.subject;
const sheetName = $('Pick Subject').item.json.sheetName;
const timestamp = Math.floor(Date.now() / 1000);
const dateStr = new Date().toISOString().split('T')[0];
return questions.map((q, index) => ({
  json: {
    ID: `AUTO-${timestamp}-${index}`,
    Date: dateStr,
    Topic: q.Topic || subject,
    Question: q.Question || q.question,
    A: q.A, B: q.B, C: q.C, D: q.D, E: q.E || '',
    Correct: q.Correct || q.correct,
    Explanation: q.Explanation || q.explanation,
    sheetName: sheetName
  }
}));
